<?php
session_start(); require_once __DIR__.'/include/db.php';
$msg=''; $ok=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $mobile=trim($_POST['mobile']??''); $password=$_POST['password']??''; $confirm=$_POST['confirm_password']??'';
 if($password!==$confirm) $msg='Passwords match nahi kar rahe.';
 elseif(!preg_match('/^[0-9]{10}$/',$mobile)) $msg='Mobile number 10 digits ka hona chahiye.';
 else { $stmt=mysqli_prepare($conn,'SELECT id FROM users WHERE email=? OR mobile=? LIMIT 1'); mysqli_stmt_bind_param($stmt,'ss',$email,$mobile); mysqli_stmt_execute($stmt); $r=mysqli_stmt_get_result($stmt); if(mysqli_num_rows($r)>0) $msg='Email ya mobile already registered hai.'; else { $hash=password_hash($password,PASSWORD_DEFAULT); $stmt=mysqli_prepare($conn,'INSERT INTO users(name,email,mobile,password) VALUES(?,?,?,?)'); mysqli_stmt_bind_param($stmt,'ssss',$name,$email,$mobile,$hash); $ok=mysqli_stmt_execute($stmt); $msg=$ok?'Account successfully create ho gaya. Ab login karein.':'Registration failed.'; }}
}
